-- Property Management core for SMART MANAGER
-- Tanzania-ready, tenant-scoped, TZS-first, and intentionally provider-safe.
-- External payment, SMS/WhatsApp, map, and storage providers are not called by SQL.
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS public.property_portfolios (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE,
  portfolio_code text NOT NULL, name text NOT NULL, description text, currency text NOT NULL DEFAULT 'TZS' CHECK (currency='TZS'), timezone text NOT NULL DEFAULT 'Africa/Dar_es_Salaam', status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Draft','Active','Archived')),
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,portfolio_code)
);
CREATE TABLE IF NOT EXISTS public.property_owners (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE,
  profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, owner_type text NOT NULL DEFAULT 'Individual' CHECK (owner_type IN ('Individual','Company','Trust','Institution')), legal_name text NOT NULL, phone text, email text, national_id text, tin text, kyc_status text NOT NULL DEFAULT 'Pending' CHECK (kyc_status IN ('Pending','Verified','Needs Review','Rejected')), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive','Blocked')), notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,profile_id), UNIQUE(company_id,national_id)
);
CREATE TABLE IF NOT EXISTS public.property_buildings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, portfolio_id uuid NOT NULL REFERENCES public.property_portfolios(id) ON DELETE RESTRICT,
  property_code text NOT NULL, name text NOT NULL, property_type text NOT NULL DEFAULT 'Building' CHECK (property_type IN ('Building','Apartment Block','House','Commercial Centre','Office Block','Warehouse','Mixed Use')), address text, country text NOT NULL DEFAULT 'Tanzania', region text, district text, ward text, village text, latitude numeric(10,7), longitude numeric(10,7), year_built integer, floors integer CHECK (floors IS NULL OR floors > 0), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Draft','Active','Maintenance','Archived')), metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,property_code), CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180))
);
CREATE TABLE IF NOT EXISTS public.property_plots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, portfolio_id uuid NOT NULL REFERENCES public.property_portfolios(id) ON DELETE RESTRICT,
  plot_code text NOT NULL, title_number text, land_use text, area_sqm numeric(18,2) NOT NULL DEFAULT 0 CHECK (area_sqm >= 0), address text, region text, district text, ward text, latitude numeric(10,7), longitude numeric(10,7), owner_id uuid REFERENCES public.property_owners(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Available' CHECK (status IN ('Available','Leased','Sold','Disputed','Archived')), metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,plot_code), CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180))
);
CREATE TABLE IF NOT EXISTS public.property_units (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, building_id uuid REFERENCES public.property_buildings(id) ON DELETE CASCADE, plot_id uuid REFERENCES public.property_plots(id) ON DELETE SET NULL, owner_id uuid REFERENCES public.property_owners(id) ON DELETE SET NULL,
  unit_code text NOT NULL, unit_type text NOT NULL DEFAULT 'Apartment' CHECK (unit_type IN ('Apartment','House','Commercial Space','Office','Shop','Warehouse','Parking','Plot','Room')), floor_label text, bedrooms integer CHECK (bedrooms IS NULL OR bedrooms >= 0), bathrooms integer CHECK (bathrooms IS NULL OR bathrooms >= 0), area_sqm numeric(18,2) NOT NULL DEFAULT 0 CHECK (area_sqm >= 0), rent_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (rent_amount >= 0), service_charge_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (service_charge_amount >= 0), deposit_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (deposit_amount >= 0), currency text NOT NULL DEFAULT 'TZS' CHECK (currency='TZS'), status text NOT NULL DEFAULT 'Available' CHECK (status IN ('Draft','Available','Reserved','Occupied','Maintenance','Sold','Off Market')), furnishing text, notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,unit_code), CHECK (building_id IS NOT NULL OR plot_id IS NOT NULL)
);
CREATE TABLE IF NOT EXISTS public.property_listings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES public.property_units(id) ON DELETE CASCADE, agent_id uuid, listing_type text NOT NULL CHECK (listing_type IN ('Rent','Sale','Leasehold')), asking_amount numeric(18,0) NOT NULL CHECK (asking_amount >= 0), commission_rate numeric(8,4) NOT NULL DEFAULT 0 CHECK (commission_rate >= 0), status text NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Published','Reserved','Closed','Withdrawn')), available_from date, published_at timestamptz, expires_at date, description text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  agent_code text NOT NULL, full_name text NOT NULL, phone text NOT NULL, email text, licence_number text, commission_rate numeric(8,4) NOT NULL DEFAULT 0 CHECK (commission_rate >= 0), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Suspended','Inactive')), branch_label text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,agent_code), UNIQUE(company_id,phone), UNIQUE(company_id,profile_id)
);
ALTER TABLE public.property_listings ADD CONSTRAINT property_listings_agent_fk FOREIGN KEY (agent_id) REFERENCES public.property_agents(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS public.property_tenants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  tenant_code text NOT NULL, full_name text NOT NULL, phone text NOT NULL, email text, national_id text, tin text, kyc_status text NOT NULL DEFAULT 'Pending' CHECK (kyc_status IN ('Pending','Verified','Needs Review','Rejected','Expired')), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Blocked','Inactive')), address text, emergency_contact text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,tenant_code), UNIQUE(company_id,phone), UNIQUE(company_id,profile_id)
);
CREATE TABLE IF NOT EXISTS public.property_tenant_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES public.property_tenants(id) ON DELETE CASCADE,
  document_type text NOT NULL, document_number text, storage_key text, file_url text, verification_status text NOT NULL DEFAULT 'Pending' CHECK (verification_status IN ('Pending','Verified','Rejected','Expired')), expires_at date, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, uploaded_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_applications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, application_number text NOT NULL, unit_id uuid NOT NULL REFERENCES public.property_units(id) ON DELETE RESTRICT, tenant_id uuid NOT NULL REFERENCES public.property_tenants(id) ON DELETE RESTRICT, agent_id uuid REFERENCES public.property_agents(id) ON DELETE SET NULL,
  requested_start_date date, proposed_rent numeric(18,0) NOT NULL DEFAULT 0 CHECK (proposed_rent >= 0), status text NOT NULL DEFAULT 'Submitted' CHECK (status IN ('Draft','Submitted','Under Review','Approved','Rejected','Withdrawn')), decision_note text, decided_by uuid, decided_at timestamptz, idempotency_key text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,application_number), UNIQUE(company_id,idempotency_key)
);
CREATE TABLE IF NOT EXISTS public.property_leases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, lease_number text NOT NULL, unit_id uuid NOT NULL REFERENCES public.property_units(id) ON DELETE RESTRICT, tenant_id uuid NOT NULL REFERENCES public.property_tenants(id) ON DELETE RESTRICT, owner_id uuid REFERENCES public.property_owners(id) ON DELETE SET NULL, application_id uuid REFERENCES public.property_applications(id) ON DELETE SET NULL,
  start_date date NOT NULL, end_date date NOT NULL, rent_amount numeric(18,0) NOT NULL CHECK (rent_amount >= 0), service_charge_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (service_charge_amount >= 0), deposit_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (deposit_amount >= 0), rent_frequency text NOT NULL DEFAULT 'Monthly' CHECK (rent_frequency IN ('Monthly','Quarterly','Biannual','Annual')), notice_days integer NOT NULL DEFAULT 30 CHECK (notice_days >= 0), status text NOT NULL DEFAULT 'Pending Approval' CHECK (status IN ('Draft','Pending Approval','Active','Renewal Due','Expired','Terminated','Handed Over')), terms jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid DEFAULT auth.uid(), approved_by uuid, approved_at timestamptz, terminated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,lease_number), CHECK (end_date > start_date)
);
CREATE TABLE IF NOT EXISTS public.property_inspections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES public.property_leases(id) ON DELETE CASCADE, inspection_type text NOT NULL CHECK (inspection_type IN ('Move In','Routine','Move Out','Handover')), inspection_date date NOT NULL DEFAULT current_date, condition_summary text, status text NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Completed','Disputed')), inspector_id uuid DEFAULT auth.uid(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_inspection_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, inspection_id uuid NOT NULL REFERENCES public.property_inspections(id) ON DELETE CASCADE, area_name text NOT NULL, condition text NOT NULL DEFAULT 'Good' CHECK (condition IN ('New','Good','Fair','Poor','Damaged','Missing')), notes text, estimated_cost numeric(18,0) NOT NULL DEFAULT 0 CHECK (estimated_cost >= 0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_handover_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES public.property_leases(id) ON DELETE CASCADE, handover_type text NOT NULL CHECK (handover_type IN ('Move In','Move Out')), handover_date date NOT NULL DEFAULT current_date, keys_count integer NOT NULL DEFAULT 0 CHECK (keys_count >= 0), meter_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, signed_by_tenant boolean NOT NULL DEFAULT false, signed_by_manager boolean NOT NULL DEFAULT false, notes text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_rent_schedules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, lease_id uuid NOT NULL REFERENCES public.property_leases(id) ON DELETE CASCADE, next_invoice_date date NOT NULL, frequency text NOT NULL DEFAULT 'Monthly', active boolean NOT NULL DEFAULT true, last_invoice_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,lease_id)
);
CREATE TABLE IF NOT EXISTS public.property_tax_fee_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, applies_to text NOT NULL DEFAULT 'Rent' CHECK (applies_to IN ('Rent','Service Charge','Utility','Late Fee','Sale','All')), rate numeric(8,4) NOT NULL DEFAULT 0 CHECK (rate >= 0), flat_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (flat_amount >= 0), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,code)
);
CREATE TABLE IF NOT EXISTS public.property_service_charges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES public.property_units(id) ON DELETE CASCADE, name text NOT NULL, amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (amount >= 0), frequency text NOT NULL DEFAULT 'Monthly', status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_utility_meters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES public.property_units(id) ON DELETE CASCADE, utility_type text NOT NULL CHECK (utility_type IN ('Electricity','Water','Gas','Internet','Other')), meter_number text, unit_of_measure text NOT NULL DEFAULT 'unit', rate numeric(18,4) NOT NULL DEFAULT 0 CHECK (rate >= 0), status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive')), UNIQUE(company_id,unit_id,utility_type,meter_number)
);
CREATE TABLE IF NOT EXISTS public.property_meter_readings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, meter_id uuid NOT NULL REFERENCES public.property_utility_meters(id) ON DELETE CASCADE, reading_date date NOT NULL DEFAULT current_date, reading_value numeric(18,4) NOT NULL CHECK (reading_value >= 0), previous_value numeric(18,4), consumption numeric(18,4), captured_by uuid DEFAULT auth.uid(), source text NOT NULL DEFAULT 'Manual' CHECK (source IN ('Manual','Import','Provider Pending')), notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,meter_id,reading_date)
);
CREATE TABLE IF NOT EXISTS public.property_invoices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, invoice_number text NOT NULL, lease_id uuid REFERENCES public.property_leases(id) ON DELETE SET NULL, tenant_id uuid NOT NULL REFERENCES public.property_tenants(id) ON DELETE RESTRICT, unit_id uuid REFERENCES public.property_units(id) ON DELETE SET NULL,
  invoice_type text NOT NULL CHECK (invoice_type IN ('Rent','Service Charge','Utility','Deposit','Late Fee','Other')), period_start date, period_end date, issue_date date NOT NULL DEFAULT current_date, due_date date NOT NULL, subtotal numeric(18,0) NOT NULL DEFAULT 0 CHECK (subtotal >= 0), tax_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), late_fee_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (late_fee_amount >= 0), total_amount numeric(18,0) NOT NULL DEFAULT 0 CHECK (total_amount >= 0), amount_paid numeric(18,0) NOT NULL DEFAULT 0 CHECK (amount_paid >= 0), status text NOT NULL DEFAULT 'Issued' CHECK (status IN ('Draft','Issued','Partially Paid','Paid','Overdue','Voided')), currency text NOT NULL DEFAULT 'TZS' CHECK (currency='TZS'), idempotency_key text NOT NULL, notes text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,invoice_number), UNIQUE(company_id,idempotency_key), UNIQUE(company_id,lease_id,invoice_type,period_start)
);
CREATE TABLE IF NOT EXISTS public.property_invoice_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, invoice_id uuid NOT NULL REFERENCES public.property_invoices(id) ON DELETE CASCADE, line_type text NOT NULL, description text NOT NULL, quantity numeric(18,4) NOT NULL DEFAULT 1 CHECK (quantity > 0), unit_amount numeric(18,0) NOT NULL CHECK (unit_amount >= 0), line_total numeric(18,0) NOT NULL CHECK (line_total >= 0), account_code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, payment_number text NOT NULL, invoice_id uuid NOT NULL REFERENCES public.property_invoices(id) ON DELETE RESTRICT, tenant_id uuid NOT NULL REFERENCES public.property_tenants(id) ON DELETE RESTRICT, amount numeric(18,0) NOT NULL CHECK (amount > 0), payment_method text NOT NULL CHECK (payment_method IN ('Cash','Bank Transfer','Mobile Money','Card','Cheque','Provider')), provider_code text, provider_reference text, status text NOT NULL DEFAULT 'Provider Pending' CHECK (status IN ('Pending','Posted','Provider Pending','Failed','Reversed')), idempotency_key text NOT NULL, paid_at timestamptz, posted_by uuid DEFAULT auth.uid(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,payment_number), UNIQUE(company_id,idempotency_key)
);
CREATE TABLE IF NOT EXISTS public.property_receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, payment_id uuid NOT NULL REFERENCES public.property_payments(id) ON DELETE RESTRICT, receipt_number text NOT NULL, channel text NOT NULL DEFAULT 'In App', recipient_phone text, issued_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,payment_id), UNIQUE(company_id,receipt_number)
);
CREATE TABLE IF NOT EXISTS public.property_contractors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, contractor_code text NOT NULL, name text NOT NULL, phone text, email text, trade text, tax_number text, status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive','Blocked')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,contractor_code)
);
CREATE TABLE IF NOT EXISTS public.property_maintenance_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, request_number text NOT NULL, unit_id uuid REFERENCES public.property_units(id) ON DELETE SET NULL, lease_id uuid REFERENCES public.property_leases(id) ON DELETE SET NULL, tenant_id uuid REFERENCES public.property_tenants(id) ON DELETE SET NULL, category text NOT NULL DEFAULT 'General', priority text NOT NULL DEFAULT 'Medium' CHECK (priority IN ('Low','Medium','High','Emergency')), title text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'Open' CHECK (status IN ('Open','Assigned','In Progress','Pending Parts','Completed','Closed','Cancelled')), requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,request_number)
);
CREATE TABLE IF NOT EXISTS public.property_work_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, work_order_number text NOT NULL, request_id uuid NOT NULL REFERENCES public.property_maintenance_requests(id) ON DELETE CASCADE, contractor_id uuid REFERENCES public.property_contractors(id) ON DELETE SET NULL, assigned_profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, estimated_cost numeric(18,0) NOT NULL DEFAULT 0 CHECK (estimated_cost >= 0), actual_cost numeric(18,0) NOT NULL DEFAULT 0 CHECK (actual_cost >= 0), status text NOT NULL DEFAULT 'Assigned' CHECK (status IN ('Assigned','In Progress','Completed','Cancelled')), due_date date, completion_note text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,work_order_number)
);
CREATE TABLE IF NOT EXISTS public.property_expenses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, expense_number text NOT NULL, property_id uuid REFERENCES public.property_buildings(id) ON DELETE SET NULL, unit_id uuid REFERENCES public.property_units(id) ON DELETE SET NULL, work_order_id uuid REFERENCES public.property_work_orders(id) ON DELETE SET NULL, category text NOT NULL, description text NOT NULL, amount numeric(18,0) NOT NULL CHECK (amount > 0), expense_date date NOT NULL DEFAULT current_date, status text NOT NULL DEFAULT 'Pending Approval' CHECK (status IN ('Draft','Pending Approval','Approved','Paid','Rejected')), payment_method text, payment_reference text, approved_by uuid, approved_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,expense_number)
);
CREATE TABLE IF NOT EXISTS public.property_budgets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, portfolio_id uuid REFERENCES public.property_portfolios(id) ON DELETE CASCADE, fiscal_year integer NOT NULL, category text NOT NULL, budget_amount numeric(18,0) NOT NULL CHECK (budget_amount >= 0), status text NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Approved','Closed')), approved_by uuid, approved_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,portfolio_id,fiscal_year,category)
);
CREATE TABLE IF NOT EXISTS public.property_insurances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid REFERENCES public.property_buildings(id) ON DELETE CASCADE, unit_id uuid REFERENCES public.property_units(id) ON DELETE CASCADE, insurer text NOT NULL, policy_number text NOT NULL, cover_type text NOT NULL, premium numeric(18,0) NOT NULL DEFAULT 0 CHECK (premium >= 0), start_date date NOT NULL, end_date date NOT NULL, status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Draft','Active','Expired','Cancelled')), notes text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,policy_number), CHECK(end_date >= start_date)
);
CREATE TABLE IF NOT EXISTS public.property_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id uuid NOT NULL, document_type text NOT NULL, title text NOT NULL, storage_key text, file_url text, document_date date, expires_at date, verification_status text NOT NULL DEFAULT 'Pending' CHECK (verification_status IN ('Pending','Verified','Rejected','Expired')), uploaded_by uuid DEFAULT auth.uid(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_notices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, lease_id uuid REFERENCES public.property_leases(id) ON DELETE CASCADE, tenant_id uuid REFERENCES public.property_tenants(id) ON DELETE CASCADE, notice_type text NOT NULL CHECK (notice_type IN ('Rent Due','Overdue','Lease Expiry','Termination','General','Maintenance')), title text NOT NULL, body text NOT NULL, notice_date date NOT NULL DEFAULT current_date, effective_date date, status text NOT NULL DEFAULT 'Issued' CHECK (status IN ('Draft','Issued','Acknowledged','Cancelled')), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_approvals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Approved','Rejected','Returned')), requested_by uuid DEFAULT auth.uid(), decided_by uuid, note text, requested_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz
);
CREATE TABLE IF NOT EXISTS public.property_ledger_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, source_type text NOT NULL, source_id uuid NOT NULL, account_code text NOT NULL, entry_type text NOT NULL CHECK (entry_type IN ('Debit','Credit')), amount numeric(18,0) NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'TZS' CHECK(currency='TZS'), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_reconciliations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, payment_id uuid REFERENCES public.property_payments(id) ON DELETE SET NULL, invoice_id uuid REFERENCES public.property_invoices(id) ON DELETE SET NULL, expected_amount numeric(18,0) NOT NULL DEFAULT 0, actual_amount numeric(18,0) NOT NULL DEFAULT 0, variance numeric(18,0) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Open' CHECK (status IN ('Open','Matched','Variance','Reviewed','Closed')), reviewed_by uuid, reviewed_at timestamptz, notes text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.property_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, recipient_profile_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, tenant_id uuid REFERENCES public.property_tenants(id) ON DELETE CASCADE, notice_id uuid REFERENCES public.property_notices(id) ON DELETE CASCADE, notification_type text NOT NULL, title text NOT NULL, body text NOT NULL, channel text NOT NULL DEFAULT 'In App' CHECK(channel IN ('In App','SMS','WhatsApp','Email','Push')), status text NOT NULL DEFAULT 'Unread' CHECK(status IN ('Unread','Read','Pending Provider','Sent','Failed')), scheduled_for timestamptz, sent_at timestamptz, dedupe_key text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,dedupe_key)
);
CREATE TABLE IF NOT EXISTS public.property_integration_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, target_module text NOT NULL CHECK(target_module IN ('Finance','Accounting','CRM','Procurement','Employee','Maintenance','Documents','Notifications')), entity_type text NOT NULL, entity_id uuid NOT NULL, event_type text NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Sent','Acknowledged','Failed')), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz
);
CREATE TABLE IF NOT EXISTS public.property_audit_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, actor_id uuid DEFAULT auth.uid(), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS property_buildings_portfolio_idx ON public.property_buildings(company_id,portfolio_id,status);
CREATE INDEX IF NOT EXISTS property_units_status_idx ON public.property_units(company_id,status,building_id);
CREATE INDEX IF NOT EXISTS property_leases_tenant_status_idx ON public.property_leases(company_id,tenant_id,status,end_date);
CREATE INDEX IF NOT EXISTS property_invoices_tenant_status_idx ON public.property_invoices(company_id,tenant_id,status,due_date);
CREATE INDEX IF NOT EXISTS property_payments_invoice_idx ON public.property_payments(company_id,invoice_id,status);
CREATE INDEX IF NOT EXISTS property_maintenance_status_idx ON public.property_maintenance_requests(company_id,status,priority);
CREATE INDEX IF NOT EXISTS property_documents_expiry_idx ON public.property_documents(company_id,expires_at);
CREATE INDEX IF NOT EXISTS property_tax_rules_scope_idx ON public.property_tax_fee_rules(company_id,applies_to,status);
CREATE INDEX IF NOT EXISTS property_audit_created_idx ON public.property_audit_log(company_id,created_at DESC);

CREATE OR REPLACE FUNCTION public.property_has_role(p_roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT coalesce(EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.company_id=public.current_company_id() AND coalesce(p.is_active,true) AND regexp_replace(lower(coalesce(p.role,'')),'[^a-z0-9]+','_','g')=ANY(p_roles)),false);
$$;
CREATE OR REPLACE FUNCTION public.property_can_view() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT public.property_has_role(ARRAY['property_administrator','property_manager','property_agent','landlord_owner','maintenance_staff','property_finance_officer','property_finance','auditor','internal_auditor','owner','admin','super_admin','super_administrator','platform_admin','platform_administrator','organization_owner','ceo','cfo','finance_manager']);
$$;
CREATE OR REPLACE FUNCTION public.property_can_manage() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT public.property_has_role(ARRAY['property_administrator','property_manager','owner','admin','super_admin','super_administrator','platform_admin','platform_administrator','organization_owner','ceo']);
$$;
CREATE OR REPLACE FUNCTION public.property_can_finance() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT public.property_has_role(ARRAY['property_administrator','property_manager','property_finance_officer','property_finance','finance_manager','cfo','owner','admin','super_administrator','platform_administrator']);
$$;
CREATE OR REPLACE FUNCTION public.property_can_approve() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT public.property_has_role(ARRAY['property_administrator','property_manager','property_finance_officer','property_finance','finance_manager','cfo','ceo','owner','admin','super_administrator','platform_administrator']);
$$;
CREATE OR REPLACE FUNCTION public.property_can_audit() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT public.property_has_role(ARRAY['auditor','internal_auditor','property_administrator','owner','admin','super_administrator','platform_administrator']);
$$;
CREATE OR REPLACE FUNCTION public.property_require(p_capability text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF p_capability='view' AND NOT public.property_can_view() THEN RAISE EXCEPTION 'Property Management access is not assigned to this profile.' USING ERRCODE='42501'; END IF;
  IF p_capability='manage' AND NOT public.property_can_manage() THEN RAISE EXCEPTION 'Property Management administration is not assigned to this profile.' USING ERRCODE='42501'; END IF;
  IF p_capability='finance' AND NOT public.property_can_finance() THEN RAISE EXCEPTION 'Property finance access is not assigned to this profile.' USING ERRCODE='42501'; END IF;
  IF p_capability='approve' AND NOT public.property_can_approve() THEN RAISE EXCEPTION 'Property approval access is not assigned to this profile.' USING ERRCODE='42501'; END IF;
  IF p_capability='audit' AND NOT public.property_can_audit() THEN RAISE EXCEPTION 'Property audit access is not assigned to this profile.' USING ERRCODE='42501'; END IF;
END; $$;
CREATE OR REPLACE FUNCTION public.property_audit(p_action text,p_entity_type text,p_entity_id uuid,p_details jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN INSERT INTO public.property_audit_log(company_id,actor_id,action,entity_type,entity_id,details) VALUES(public.current_company_id(),auth.uid(),p_action,p_entity_type,p_entity_id,coalesce(p_details,'{}'::jsonb)); END; $$;
CREATE OR REPLACE FUNCTION public.property_touch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.property_immutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Property financial and audit history is immutable.' USING ERRCODE='55000'; END; $$;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['property_portfolios','property_owners','property_buildings','property_plots','property_units','property_listings','property_agents','property_tenants','property_tenant_documents','property_applications','property_leases','property_inspections','property_inspection_items','property_handover_records','property_rent_schedules','property_service_charges','property_utility_meters','property_meter_readings','property_tax_fee_rules','property_invoices','property_invoice_lines','property_payments','property_receipts','property_contractors','property_maintenance_requests','property_work_orders','property_expenses','property_budgets','property_insurances','property_documents','property_notices','property_approvals','property_ledger_entries','property_reconciliations','property_notifications','property_integration_events','property_audit_log'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_no_direct_access',t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (false) WITH CHECK (false)',t||'_no_direct_access',t);
  END LOOP;
END $$;
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['property_portfolios','property_owners','property_buildings','property_plots','property_units','property_listings','property_agents','property_tenants','property_applications','property_leases','property_rent_schedules','property_tax_fee_rules','property_service_charges','property_contractors','property_maintenance_requests','property_work_orders','property_expenses','property_budgets'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I',t||'_touch',t);
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.property_touch()',t||'_touch',t);
  END LOOP;
END $$;
CREATE TRIGGER property_ledger_immutable BEFORE UPDATE OR DELETE ON public.property_ledger_entries FOR EACH ROW EXECUTE FUNCTION public.property_immutable_guard();
CREATE TRIGGER property_audit_immutable BEFORE UPDATE OR DELETE ON public.property_audit_log FOR EACH ROW EXECUTE FUNCTION public.property_immutable_guard();
CREATE TRIGGER property_receipt_immutable BEFORE UPDATE OR DELETE ON public.property_receipts FOR EACH ROW EXECUTE FUNCTION public.property_immutable_guard();

CREATE OR REPLACE FUNCTION public.property_ledger_post(p_source_type text,p_source_id uuid,p_entries jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE e jsonb; debit_total numeric:=0; credit_total numeric:=0;
BEGIN
  FOR e IN SELECT value FROM jsonb_array_elements(coalesce(p_entries,'[]'::jsonb)) LOOP
    IF coalesce((e->>'amount')::numeric,0)<=0 OR coalesce(e->>'accountCode','')='' OR e->>'entryType' NOT IN ('Debit','Credit') THEN RAISE EXCEPTION 'Invalid Property Management ledger entry.' USING ERRCODE='22023'; END IF;
    IF e->>'entryType'='Debit' THEN debit_total:=debit_total+(e->>'amount')::numeric; ELSE credit_total:=credit_total+(e->>'amount')::numeric; END IF;
    INSERT INTO public.property_ledger_entries(company_id,source_type,source_id,account_code,entry_type,amount,metadata) VALUES(public.current_company_id(),p_source_type,p_source_id,e->>'accountCode',e->>'entryType',(e->>'amount')::numeric,coalesce(e->'metadata','{}'::jsonb));
  END LOOP;
  IF debit_total=0 OR debit_total<>credit_total THEN RAISE EXCEPTION 'Property Management ledger posting is not balanced.' USING ERRCODE='22023'; END IF;
END; $$;

CREATE OR REPLACE FUNCTION public.property_snapshot(p_limit integer DEFAULT 100) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE c uuid:=public.current_company_id(); l integer:=greatest(1,least(coalesce(p_limit,100),200)); v_uid uuid:=auth.uid(); v_restricted boolean:=public.property_has_role(ARRAY['tenant','property_agent','landlord_owner','maintenance_staff']);
BEGIN
  PERFORM public.property_require('view');
  RETURN jsonb_build_object(
    'companyId',c,'currency','TZS','timezone','Africa/Dar_es_Salaam','viewer',jsonb_build_object('id',v_uid,'role',(SELECT role FROM public.profiles WHERE id=v_uid)),
    'permissions',jsonb_build_object('canManage',public.property_can_manage(),'canFinance',public.property_can_finance(),'canApprove',public.property_can_approve(),'canAudit',public.property_can_audit()),
    'metrics',jsonb_build_object(
      'portfolioCount',(SELECT count(*) FROM public.property_portfolios WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid)),
      'propertyCount',(SELECT count(*) FROM public.property_buildings WHERE company_id=c AND (NOT v_restricted OR id IN (SELECT u.building_id FROM public.property_units u JOIN public.property_leases l ON l.unit_id=u.id JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'unitCount',(SELECT count(*) FROM public.property_units WHERE company_id=c AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR id IN (SELECT l.unit_id FROM public.property_leases l JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'occupiedUnits',(SELECT count(*) FROM public.property_units WHERE company_id=c AND status='Occupied' AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR id IN (SELECT l.unit_id FROM public.property_leases l JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'vacantUnits',(SELECT count(*) FROM public.property_units WHERE company_id=c AND status IN ('Available','Reserved') AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid))),
      'occupancyRate',coalesce(round(100.0*(SELECT count(*) FROM public.property_units WHERE company_id=c AND status='Occupied')/nullif((SELECT count(*) FROM public.property_units WHERE company_id=c AND status NOT IN ('Sold','Off Market')),0),2),0),
      'rentalIncome',coalesce((SELECT sum(amount) FROM public.property_payments WHERE company_id=c AND status='Posted' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),0),
      'outstandingRent',coalesce((SELECT sum(total_amount-amount_paid) FROM public.property_invoices WHERE company_id=c AND status IN ('Issued','Partially Paid','Overdue') AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),0),
      'overdueAccounts',(SELECT count(*) FROM public.property_invoices WHERE company_id=c AND status='Overdue' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),
      'maintenanceCosts',coalesce((SELECT sum(actual_cost) FROM public.property_work_orders w WHERE w.company_id=c AND w.status='Completed' AND (NOT v_restricted OR w.request_id IN (SELECT r.id FROM public.property_maintenance_requests r JOIN public.property_leases l ON l.id=r.lease_id JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),0),
      'propertyExpenses',coalesce((SELECT sum(amount) FROM public.property_expenses WHERE company_id=c AND status IN ('Approved','Paid') AND (NOT v_restricted OR created_by=v_uid)),0),
      'upcomingLeaseExpiries',(SELECT count(*) FROM public.property_leases WHERE company_id=c AND status='Active' AND end_date BETWEEN current_date AND current_date+interval '90 days' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),
      'openMaintenance',(SELECT count(*) FROM public.property_maintenance_requests WHERE company_id=c AND status NOT IN ('Closed','Cancelled') AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)))
    ),
    'portfolios',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,portfolio_code AS "portfolioCode",name,description,currency,timezone,status,created_at AS "createdAt" FROM public.property_portfolios WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid) LIMIT l)x),'[]'::jsonb),
    'owners',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.legal_name) FROM (SELECT id,legal_name AS "legalName",owner_type AS "ownerType",phone,email,kyc_status AS "kycStatus",status,created_at AS "createdAt" FROM public.property_owners WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid) LIMIT l)x),'[]'::jsonb),
    'buildings',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT b.id,b.property_code AS "propertyCode",b.name,b.property_type AS "propertyType",b.address,b.region,b.district,b.ward,b.latitude,b.longitude,b.status,p.name AS "portfolioName" FROM public.property_buildings b JOIN public.property_portfolios p ON p.id=b.portfolio_id WHERE b.company_id=c AND (NOT v_restricted OR b.id IN (SELECT u.building_id FROM public.property_units u JOIN public.property_leases l2 ON l2.unit_id=u.id JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'plots',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.plot_code) FROM (SELECT id,plot_code AS "plotCode",title_number AS "titleNumber",land_use AS "landUse",area_sqm AS "areaSqm",region,district,ward,status FROM public.property_plots WHERE company_id=c AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'listings',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT l.id,l.unit_id AS "unitId",l.agent_id AS "agentId",l.listing_type AS "listingType",l.asking_amount AS "askingAmount",l.commission_rate AS "commissionRate",l.status,l.available_from AS "availableFrom",l.expires_at AS "expiresAt",l.description,l.created_at AS "createdAt",u.unit_code AS "unitCode" FROM public.property_listings l JOIN public.property_units u ON u.id=l.unit_id WHERE l.company_id=c AND (NOT v_restricted OR l.agent_id IN (SELECT id FROM public.property_agents WHERE profile_id=v_uid) OR l.unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'units',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.unit_code) FROM (SELECT u.id,u.unit_code AS "unitCode",u.unit_type AS "unitType",u.floor_label AS "floorLabel",u.bedrooms,u.bathrooms,u.area_sqm AS "areaSqm",u.rent_amount AS "rentAmount",u.service_charge_amount AS "serviceChargeAmount",u.deposit_amount AS "depositAmount",u.status,u.building_id AS "buildingId",b.name AS "buildingName" FROM public.property_units u LEFT JOIN public.property_buildings b ON b.id=u.building_id WHERE u.company_id=c AND (NOT v_restricted OR u.owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR u.id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'agents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.full_name) FROM (SELECT id,agent_code AS "agentCode",full_name AS "fullName",phone,email,licence_number AS "licenceNumber",commission_rate AS "commissionRate",status FROM public.property_agents WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid) LIMIT l)x),'[]'::jsonb),
    'taxRules',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.code) FROM (SELECT id,code,name,applies_to AS "appliesTo",rate,flat_amount AS "flatAmount",status FROM public.property_tax_fee_rules WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'meters',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.utility_type) FROM (SELECT id,unit_id AS "unitId",utility_type AS "utilityType",meter_number AS "meterNumber",unit_of_measure AS "unitOfMeasure",rate,status FROM public.property_utility_meters WHERE company_id=c AND (NOT v_restricted OR unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'serviceCharges',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,unit_id AS "unitId",name,amount,frequency,status,created_at AS "createdAt" FROM public.property_service_charges WHERE company_id=c AND (NOT v_restricted OR unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'contractors',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,contractor_code AS "contractorCode",name,phone,email,trade,tax_number AS "taxNumber",status FROM public.property_contractors WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'tenants',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.full_name) FROM (SELECT id,tenant_code AS "tenantCode",full_name AS "fullName",phone,email,kyc_status AS "kycStatus",status,created_at AS "createdAt" FROM public.property_tenants WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid OR created_by=v_uid) LIMIT l)x),'[]'::jsonb),
    'applications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,application_number AS "applicationNumber",unit_id AS "unitId",tenant_id AS "tenantId",proposed_rent AS "proposedRent",requested_start_date AS "requestedStartDate",status,decision_note AS "decisionNote",created_at AS "createdAt" FROM public.property_applications WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR agent_id IN (SELECT id FROM public.property_agents WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'leases',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.end_date) FROM (SELECT id,lease_number AS "leaseNumber",unit_id AS "unitId",tenant_id AS "tenantId",owner_id AS "ownerId",start_date AS "startDate",end_date AS "endDate",rent_amount AS "rentAmount",service_charge_amount AS "serviceChargeAmount",deposit_amount AS "depositAmount",rent_frequency AS "rentFrequency",status,notice_days AS "noticeDays" FROM public.property_leases WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'invoices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.due_date DESC) FROM (SELECT id,invoice_number AS "invoiceNumber",invoice_type AS "invoiceType",lease_id AS "leaseId",tenant_id AS "tenantId",unit_id AS "unitId",period_start AS "periodStart",period_end AS "periodEnd",issue_date AS "issueDate",due_date AS "dueDate",subtotal,tax_amount AS "taxAmount",late_fee_amount AS "lateFeeAmount",total_amount AS "totalAmount",amount_paid AS "amountPaid",status,currency FROM public.property_invoices WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,payment_number AS "paymentNumber",invoice_id AS "invoiceId",tenant_id AS "tenantId",amount,payment_method AS "paymentMethod",provider_code AS "providerCode",provider_reference AS "providerReference",status,paid_at AS "paidAt",created_at AS "createdAt" FROM public.property_payments WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'receipts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.issued_at DESC) FROM (SELECT r.id,r.payment_id AS "paymentId",r.receipt_number AS "receiptNumber",r.channel,r.recipient_phone AS "recipientPhone",r.issued_at AS "issuedAt" FROM public.property_receipts r JOIN public.property_payments p ON p.id=r.payment_id WHERE r.company_id=c AND (NOT v_restricted OR p.tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'maintenanceRequests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.requested_at DESC) FROM (SELECT id,request_number AS "requestNumber",unit_id AS "unitId",tenant_id AS "tenantId",category,priority,title,description,status,requested_at AS "requestedAt",completed_at AS "completedAt" FROM public.property_maintenance_requests WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR created_by=v_uid) LIMIT l)x),'[]'::jsonb),
    'inspections',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.inspection_date DESC) FROM (SELECT id,lease_id AS "leaseId",inspection_type AS "inspectionType",inspection_date AS "inspectionDate",condition_summary AS "conditionSummary",status,inspector_id AS "inspectorId",created_at AS "createdAt" FROM public.property_inspections WHERE company_id=c AND (NOT v_restricted OR lease_id IN (SELECT l2.id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'handovers',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.handover_date DESC) FROM (SELECT id,lease_id AS "leaseId",handover_type AS "handoverType",handover_date AS "handoverDate",keys_count AS "keysCount",signed_by_tenant AS "signedByTenant",signed_by_manager AS "signedByManager",notes,created_at AS "createdAt" FROM public.property_handover_records WHERE company_id=c AND (NOT v_restricted OR lease_id IN (SELECT l2.id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT l)x),'[]'::jsonb),
    'workOrders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,work_order_number AS "workOrderNumber",request_id AS "requestId",contractor_id AS "contractorId",assigned_profile_id AS "assignedProfileId",estimated_cost AS "estimatedCost",actual_cost AS "actualCost",status,due_date AS "dueDate",completion_note AS "completionNote" FROM public.property_work_orders WHERE company_id=c AND (NOT v_restricted OR assigned_profile_id=v_uid) LIMIT l)x),'[]'::jsonb),
    'expenses',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.expense_date DESC) FROM (SELECT id,expense_number AS "expenseNumber",property_id AS "propertyId",unit_id AS "unitId",category,description,amount,expense_date AS "expenseDate",status,payment_method AS "paymentMethod" FROM public.property_expenses WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid) LIMIT l)x),'[]'::jsonb),
    'budgets',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.fiscal_year DESC,x.category) FROM (SELECT id,portfolio_id AS "portfolioId",fiscal_year AS "fiscalYear",category,budget_amount AS "budgetAmount",status,approved_by AS "approvedBy",approved_at AS "approvedAt",created_at AS "createdAt" FROM public.property_budgets WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'insurances',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.end_date) FROM (SELECT id,property_id AS "propertyId",unit_id AS "unitId",insurer,policy_number AS "policyNumber",cover_type AS "coverType",premium,start_date AS "startDate",end_date AS "endDate",status,notes FROM public.property_insurances WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'reconciliations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,payment_id AS "paymentId",invoice_id AS "invoiceId",expected_amount AS "expectedAmount",actual_amount AS "actualAmount",variance,status,notes,created_at AS "createdAt" FROM public.property_reconciliations WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'approvals',CASE WHEN public.property_can_approve() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.requested_at DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",action,status,requested_by AS "requestedBy",decided_by AS "decidedBy",note,requested_at AS "requestedAt",decided_at AS "decidedAt" FROM public.property_approvals WHERE company_id=c LIMIT l)x),'[]'::jsonb) ELSE '[]'::jsonb END,
    'integrationEvents',CASE WHEN public.property_can_audit() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,target_module AS "targetModule",entity_type AS "entityType",entity_id AS "entityId",event_type AS "eventType",status,created_at AS "createdAt" FROM public.property_integration_events WHERE company_id=c LIMIT l)x),'[]'::jsonb) ELSE '[]'::jsonb END,
    'documents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",document_type AS "documentType",title,storage_key AS "storageKey",file_url AS "fileUrl",document_date AS "documentDate",expires_at AS "expiresAt",verification_status AS "verificationStatus",created_at AS "createdAt" FROM public.property_documents WHERE company_id=c LIMIT l)x),'[]'::jsonb),
    'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,notification_type AS "notificationType",title,body,channel,status,scheduled_for AS "scheduledFor",created_at AS "createdAt" FROM public.property_notifications WHERE company_id=c AND (recipient_profile_id=v_uid OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR NOT v_restricted) LIMIT l)x),'[]'::jsonb),
    'audit',CASE WHEN public.property_can_audit() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,actor_id AS "actorId",action,entity_type AS "entityType",entity_id AS "entityId",details,created_at AS "createdAt" FROM public.property_audit_log WHERE company_id=c LIMIT l)x),'[]'::jsonb) ELSE '[]'::jsonb END
  );
END; $$;

CREATE OR REPLACE FUNCTION public.property_tenant_snapshot(p_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE c uuid:=public.current_company_id(); l integer:=greatest(1,least(coalesce(p_limit,50),100)); v_tenant public.property_tenants%ROWTYPE;
BEGIN
  SELECT * INTO v_tenant FROM public.property_tenants WHERE company_id=c AND profile_id=auth.uid() AND status='Active' LIMIT 1;
  IF v_tenant.id IS NULL THEN RAISE EXCEPTION 'No active Property Management tenant profile is linked to this account.' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'tenant',jsonb_build_object('id',v_tenant.id,'tenantCode',v_tenant.tenant_code,'fullName',v_tenant.full_name,'phone',v_tenant.phone,'email',v_tenant.email,'kycStatus',v_tenant.kyc_status,'status',v_tenant.status),
    'currency','TZS','timezone','Africa/Dar_es_Salaam',
    'leases',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.end_date) FROM (SELECT id,lease_number AS "leaseNumber",unit_id AS "unitId",start_date AS "startDate",end_date AS "endDate",rent_amount AS "rentAmount",service_charge_amount AS "serviceChargeAmount",deposit_amount AS "depositAmount",rent_frequency AS "rentFrequency",status,notice_days AS "noticeDays" FROM public.property_leases WHERE company_id=c AND tenant_id=v_tenant.id LIMIT l)x),'[]'::jsonb),
    'invoices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.due_date DESC) FROM (SELECT id,invoice_number AS "invoiceNumber",invoice_type AS "invoiceType",lease_id AS "leaseId",unit_id AS "unitId",period_start AS "periodStart",period_end AS "periodEnd",due_date AS "dueDate",total_amount AS "totalAmount",amount_paid AS "amountPaid",status,currency FROM public.property_invoices WHERE company_id=c AND tenant_id=v_tenant.id LIMIT l)x),'[]'::jsonb),
    'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,payment_number AS "paymentNumber",invoice_id AS "invoiceId",amount,payment_method AS "paymentMethod",provider_reference AS "providerReference",status,paid_at AS "paidAt",created_at AS "createdAt" FROM public.property_payments WHERE company_id=c AND tenant_id=v_tenant.id LIMIT l)x),'[]'::jsonb),
    'maintenanceRequests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.requested_at DESC) FROM (SELECT id,request_number AS "requestNumber",unit_id AS "unitId",category,priority,title,description,status,requested_at AS "requestedAt",completed_at AS "completedAt" FROM public.property_maintenance_requests WHERE company_id=c AND tenant_id=v_tenant.id LIMIT l)x),'[]'::jsonb),
    'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,notification_type AS "notificationType",title,body,channel,status,created_at AS "createdAt" FROM public.property_notifications WHERE company_id=c AND (tenant_id=v_tenant.id OR recipient_profile_id=auth.uid()) LIMIT l)x),'[]'::jsonb),
    'documents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",document_type AS "documentType",title,file_url AS "fileUrl",expires_at AS "expiresAt",verification_status AS "verificationStatus",created_at AS "createdAt" FROM public.property_documents WHERE company_id=c AND ((entity_type='Tenant' AND entity_id=v_tenant.id) OR (entity_type='Lease' AND entity_id IN (SELECT id FROM public.property_leases WHERE company_id=c AND tenant_id=v_tenant.id))) LIMIT l)x),'[]'::jsonb)
  );
END; $$;

CREATE OR REPLACE FUNCTION public.property_action(p_action text,p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE c uuid:=public.current_company_id(); v_id uuid; v_now timestamptz:=now(); v_uid uuid:=auth.uid(); v_tx record; v_unit public.property_units%ROWTYPE; v_lease public.property_leases%ROWTYPE; v_tenant public.property_tenants%ROWTYPE; v_invoice public.property_invoices%ROWTYPE; v_payment public.property_payments%ROWTYPE; v_request public.property_maintenance_requests%ROWTYPE; v_amount numeric; v_period_start date; v_period_end date; v_due date; v_status text; v_entries jsonb; v_prev numeric; v_rate numeric; v_consumption numeric; v_total numeric; v_lease_row record; v_limit integer;
BEGIN
  IF p_action IN ('REGISTER_METER','REGISTER_CONTRACTOR','REGISTER_PORTFOLIO','REGISTER_OWNER','REGISTER_BUILDING','REGISTER_PLOT','REGISTER_UNIT','REGISTER_LISTING','REGISTER_AGENT','REGISTER_TENANT','APPROVE_APPLICATION','CREATE_LEASE','RECORD_HANDOVER','RECORD_INSPECTION','REGISTER_INSURANCE','CREATE_BUDGET','REGISTER_SERVICE_CHARGE','CREATE_DOCUMENT','ISSUE_NOTICE','TERMINATE_LEASE','ASSIGN_WORK_ORDER','CREATE_EXPENSE') THEN PERFORM public.property_require('manage'); END IF;
  IF p_action IN ('APPROVE_LEASE','APPROVE_EXPENSE') THEN PERFORM public.property_require('approve'); END IF;
  IF p_action='CREATE_TAX_RULE' THEN PERFORM public.property_require('finance'); END IF;
  IF p_action='RECONCILE_PAYMENT' THEN PERFORM public.property_require('finance'); END IF;
  IF p_action='RECORD_PAYMENT' AND NOT (public.property_can_finance() OR public.property_has_role(ARRAY['tenant','customer'])) THEN RAISE EXCEPTION 'Property payment access is not assigned to this profile.' USING ERRCODE='42501'; END IF;
  IF p_action IN ('GENERATE_INVOICE','RUN_PROPERTY_CONTROLS') THEN PERFORM public.property_require('manage'); END IF;
  IF p_action IN ('SUBMIT_APPLICATION','CREATE_MAINTENANCE_REQUEST','RECORD_METER_READING') AND NOT (public.property_can_view() OR public.property_has_role(ARRAY['tenant','customer'])) THEN RAISE EXCEPTION 'Property action is not assigned to this profile.' USING ERRCODE='42501'; END IF;

  IF p_action='CREATE_TAX_RULE' THEN
    INSERT INTO public.property_tax_fee_rules(company_id,code,name,applies_to,rate,flat_amount,status) VALUES(c,upper(trim(p_payload->>'code')),trim(p_payload->>'name'),coalesce(p_payload->>'appliesTo','Rent'),coalesce(nullif(p_payload->>'rate','')::numeric,0),coalesce(nullif(p_payload->>'flatAmount','')::numeric,0),coalesce(p_payload->>'status','Active')) RETURNING id INTO v_id;
    PERFORM public.property_audit('TAX_RULE_CREATED','TaxFeeRule',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_METER' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Unit is unavailable for meter setup.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_utility_meters(company_id,unit_id,utility_type,meter_number,unit_of_measure,rate,status) VALUES(c,(p_payload->>'unitId')::uuid,coalesce(p_payload->>'utilityType','Electricity'),nullif(trim(p_payload->>'meterNumber'),''),coalesce(p_payload->>'unitOfMeasure','unit'),coalesce(nullif(p_payload->>'rate','')::numeric,0),coalesce(p_payload->>'status','Active')) RETURNING id INTO v_id;
    PERFORM public.property_audit('METER_REGISTERED','UtilityMeter',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_CONTRACTOR' THEN
    INSERT INTO public.property_contractors(company_id,contractor_code,name,phone,email,trade,tax_number,status) VALUES(c,upper(trim(p_payload->>'contractorCode')),trim(p_payload->>'name'),nullif(trim(p_payload->>'phone'),''),nullif(trim(p_payload->>'email'),''),nullif(trim(p_payload->>'trade'),''),nullif(trim(p_payload->>'taxNumber'),''),coalesce(p_payload->>'status','Active')) RETURNING id INTO v_id;
    PERFORM public.property_audit('CONTRACTOR_REGISTERED','Contractor',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_PORTFOLIO' THEN
    INSERT INTO public.property_portfolios(company_id,portfolio_code,name,description) VALUES(c,upper(trim(p_payload->>'portfolioCode')),trim(p_payload->>'name'),nullif(trim(p_payload->>'description'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('PORTFOLIO_REGISTERED','Portfolio',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_OWNER' THEN
    IF nullif(trim(p_payload->>'profileId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(p_payload->>'profileId')::uuid AND company_id=c AND coalesce(is_active,true)) THEN RAISE EXCEPTION 'Owner profile is not active in this workspace.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.property_owners(company_id,profile_id,owner_type,legal_name,phone,email,national_id,tin,kyc_status,notes) VALUES(c,nullif(p_payload->>'profileId','')::uuid,coalesce(p_payload->>'ownerType','Individual'),trim(p_payload->>'legalName'),trim(p_payload->>'phone'),nullif(trim(p_payload->>'email'),''),nullif(trim(p_payload->>'nationalId'),''),nullif(trim(p_payload->>'tin'),''),coalesce(p_payload->>'kycStatus','Pending'),nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('OWNER_REGISTERED','Owner',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_BUILDING' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_portfolios WHERE id=(p_payload->>'portfolioId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Portfolio is unavailable in this workspace.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_buildings(company_id,portfolio_id,property_code,name,property_type,address,region,district,ward,village,latitude,longitude,year_built,floors,status) VALUES(c,(p_payload->>'portfolioId')::uuid,upper(trim(p_payload->>'propertyCode')),trim(p_payload->>'name'),coalesce(p_payload->>'propertyType','Building'),nullif(trim(p_payload->>'address'),''),nullif(trim(p_payload->>'region'),''),nullif(trim(p_payload->>'district'),''),nullif(trim(p_payload->>'ward'),''),nullif(trim(p_payload->>'village'),''),nullif(p_payload->>'latitude','')::numeric,nullif(p_payload->>'longitude','')::numeric,nullif(p_payload->>'yearBuilt','')::integer,nullif(p_payload->>'floors','')::integer,coalesce(p_payload->>'status','Active')) RETURNING id INTO v_id;
    PERFORM public.property_audit('BUILDING_REGISTERED','Building',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_PLOT' THEN
    INSERT INTO public.property_plots(company_id,portfolio_id,plot_code,title_number,land_use,area_sqm,address,region,district,ward,latitude,longitude,owner_id,status) VALUES(c,(p_payload->>'portfolioId')::uuid,upper(trim(p_payload->>'plotCode')),nullif(trim(p_payload->>'titleNumber'),''),nullif(trim(p_payload->>'landUse'),''),coalesce(nullif(p_payload->>'areaSqm','')::numeric,0),nullif(trim(p_payload->>'address'),''),nullif(trim(p_payload->>'region'),''),nullif(trim(p_payload->>'district'),''),nullif(trim(p_payload->>'ward'),''),nullif(p_payload->>'latitude','')::numeric,nullif(p_payload->>'longitude','')::numeric,nullif(p_payload->>'ownerId','')::uuid,coalesce(p_payload->>'status','Available')) RETURNING id INTO v_id;
    PERFORM public.property_audit('PLOT_REGISTERED','Plot',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Available');
  ELSIF p_action='REGISTER_UNIT' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_buildings WHERE id=nullif(p_payload->>'buildingId','')::uuid AND company_id=c) AND NOT EXISTS(SELECT 1 FROM public.property_plots WHERE id=nullif(p_payload->>'plotId','')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Unit must belong to a property in this workspace.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_units(company_id,building_id,plot_id,owner_id,unit_code,unit_type,floor_label,bedrooms,bathrooms,area_sqm,rent_amount,service_charge_amount,deposit_amount,status,furnishing,notes) VALUES(c,nullif(p_payload->>'buildingId','')::uuid,nullif(p_payload->>'plotId','')::uuid,nullif(p_payload->>'ownerId','')::uuid,upper(trim(p_payload->>'unitCode')),coalesce(p_payload->>'unitType','Apartment'),nullif(trim(p_payload->>'floorLabel'),''),nullif(p_payload->>'bedrooms','')::integer,nullif(p_payload->>'bathrooms','')::integer,coalesce(nullif(p_payload->>'areaSqm','')::numeric,0),coalesce(nullif(p_payload->>'rentAmount','')::numeric,0),coalesce(nullif(p_payload->>'serviceChargeAmount','')::numeric,0),coalesce(nullif(p_payload->>'depositAmount','')::numeric,0),coalesce(p_payload->>'status','Available'),nullif(trim(p_payload->>'furnishing'),''),nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('UNIT_REGISTERED','Unit',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',(SELECT status FROM public.property_units WHERE id=v_id));
  ELSIF p_action='REGISTER_LISTING' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Unit is unavailable for listing.' USING ERRCODE='22023'; END IF;
    IF nullif(trim(p_payload->>'agentId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.property_agents WHERE id=(p_payload->>'agentId')::uuid AND company_id=c AND status='Active') THEN RAISE EXCEPTION 'Listing agent is unavailable in this workspace.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_listings(company_id,unit_id,agent_id,listing_type,asking_amount,commission_rate,status,available_from,expires_at,description) VALUES(c,(p_payload->>'unitId')::uuid,nullif(p_payload->>'agentId','')::uuid,coalesce(p_payload->>'listingType','Rent'),coalesce(nullif(p_payload->>'askingAmount','')::numeric,0),coalesce(nullif(p_payload->>'commissionRate','')::numeric,0),coalesce(p_payload->>'status','Draft'),nullif(p_payload->>'availableFrom','')::date,nullif(p_payload->>'expiresAt','')::date,nullif(trim(p_payload->>'description'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('LISTING_REGISTERED','Listing',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',coalesce(p_payload->>'status','Draft'));
  ELSIF p_action='REGISTER_AGENT' THEN
    IF nullif(trim(p_payload->>'profileId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(p_payload->>'profileId')::uuid AND company_id=c AND coalesce(is_active,true)) THEN RAISE EXCEPTION 'Agent profile is not active in this workspace.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.property_agents(company_id,profile_id,agent_code,full_name,phone,email,licence_number,commission_rate,status,branch_label) VALUES(c,nullif(p_payload->>'profileId','')::uuid,upper(trim(p_payload->>'agentCode')),trim(p_payload->>'fullName'),trim(p_payload->>'phone'),nullif(trim(p_payload->>'email'),''),nullif(trim(p_payload->>'licenceNumber'),''),coalesce(nullif(p_payload->>'commissionRate','')::numeric,0),coalesce(p_payload->>'status','Active'),nullif(trim(p_payload->>'branchLabel'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('AGENT_REGISTERED','Agent',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='REGISTER_TENANT' THEN
    IF nullif(trim(p_payload->>'profileId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(p_payload->>'profileId')::uuid AND company_id=c AND coalesce(is_active,true)) THEN RAISE EXCEPTION 'Tenant profile is not active in this workspace.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.property_tenants(company_id,profile_id,tenant_code,full_name,phone,email,national_id,tin,kyc_status,status,address,emergency_contact) VALUES(c,nullif(p_payload->>'profileId','')::uuid,upper(trim(p_payload->>'tenantCode')),trim(p_payload->>'fullName'),trim(p_payload->>'phone'),nullif(trim(p_payload->>'email'),''),nullif(trim(p_payload->>'nationalId'),''),nullif(trim(p_payload->>'tin'),''),coalesce(p_payload->>'kycStatus','Pending'),coalesce(p_payload->>'status','Active'),nullif(trim(p_payload->>'address'),''),nullif(trim(p_payload->>'emergencyContact'),'')) RETURNING id INTO v_id;
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'CRM','Tenant',v_id,'TENANT_REGISTERED',jsonb_build_object('tenantId',v_id));
    PERFORM public.property_audit('TENANT_REGISTERED','Tenant',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Active');
  ELSIF p_action='SUBMIT_APPLICATION' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c AND status IN ('Available','Reserved')) THEN RAISE EXCEPTION 'The selected unit is not available for application.' USING ERRCODE='22023'; END IF;
    SELECT * INTO v_tenant FROM public.property_tenants WHERE id=(p_payload->>'tenantId')::uuid AND company_id=c AND status='Active';
    IF v_tenant.id IS NULL THEN RAISE EXCEPTION 'Tenant is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_applications(company_id,application_number,unit_id,tenant_id,agent_id,requested_start_date,proposed_rent,status,idempotency_key) VALUES(c,'PA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),(p_payload->>'unitId')::uuid,v_tenant.id,nullif(p_payload->>'agentId','')::uuid,nullif(p_payload->>'requestedStartDate','')::date,coalesce(nullif(p_payload->>'proposedRent','')::numeric,0),'Submitted',trim(p_payload->>'idempotencyKey')) RETURNING id INTO v_id;
    INSERT INTO public.property_approvals(company_id,entity_type,entity_id,action,requested_by) VALUES(c,'Application',v_id,'Approve Application',v_uid);
    UPDATE public.property_units SET status='Reserved' WHERE id=(p_payload->>'unitId')::uuid AND company_id=c AND status='Available';
    PERFORM public.property_audit('APPLICATION_SUBMITTED','Application',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Submitted');
  ELSIF p_action='APPROVE_APPLICATION' THEN
    SELECT * INTO v_tx FROM public.property_applications WHERE id=(p_payload->>'applicationId')::uuid AND company_id=c FOR UPDATE;
    IF v_tx IS NULL OR v_tx.status NOT IN ('Submitted','Under Review') THEN RAISE EXCEPTION 'Application is not awaiting a decision.' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.property_approvals WHERE company_id=c AND entity_type='Application' AND entity_id=(p_payload->>'applicationId')::uuid AND requested_by=v_uid AND status='Pending') THEN RAISE EXCEPTION 'The application maker cannot approve their own application.' USING ERRCODE='42501'; END IF;
    UPDATE public.property_applications SET status='Approved',decision_note=nullif(trim(p_payload->>'note'),''),decided_by=v_uid,decided_at=v_now WHERE id=(p_payload->>'applicationId')::uuid;
    UPDATE public.property_approvals SET status='Approved',decided_by=v_uid,decided_at=v_now,note=nullif(trim(p_payload->>'note'),'') WHERE company_id=c AND entity_type='Application' AND entity_id=(p_payload->>'applicationId')::uuid AND status='Pending';
    PERFORM public.property_audit('APPLICATION_APPROVED','Application',(p_payload->>'applicationId')::uuid,p_payload); RETURN jsonb_build_object('id',(p_payload->>'applicationId')::uuid,'status','Approved');
  ELSIF p_action='CREATE_LEASE' THEN
    SELECT * INTO v_unit FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c FOR UPDATE;
    SELECT * INTO v_tenant FROM public.property_tenants WHERE id=(p_payload->>'tenantId')::uuid AND company_id=c AND status='Active';
    IF v_unit.id IS NULL OR v_tenant.id IS NULL THEN RAISE EXCEPTION 'Unit or tenant is unavailable.' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.property_leases WHERE company_id=c AND unit_id=v_unit.id AND status IN ('Pending Approval','Active','Renewal Due') AND daterange(start_date,end_date,'[]') && daterange((p_payload->>'startDate')::date,(p_payload->>'endDate')::date,'[]')) THEN RAISE EXCEPTION 'The selected unit has an overlapping lease.' USING ERRCODE='23505'; END IF;
    INSERT INTO public.property_leases(company_id,lease_number,unit_id,tenant_id,owner_id,application_id,start_date,end_date,rent_amount,service_charge_amount,deposit_amount,rent_frequency,notice_days,status,terms) VALUES(c,'PL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_unit.id,v_tenant.id,v_unit.owner_id,nullif(p_payload->>'applicationId','')::uuid,(p_payload->>'startDate')::date,(p_payload->>'endDate')::date,coalesce(nullif(p_payload->>'rentAmount','')::numeric,v_unit.rent_amount),coalesce(nullif(p_payload->>'serviceChargeAmount','')::numeric,v_unit.service_charge_amount),coalesce(nullif(p_payload->>'depositAmount','')::numeric,v_unit.deposit_amount),coalesce(p_payload->>'rentFrequency','Monthly'),coalesce(nullif(p_payload->>'noticeDays','')::integer,30),CASE WHEN coalesce(p_payload->>'status','Active')='Active' THEN 'Active' ELSE 'Pending Approval' END,coalesce(p_payload->'terms','{}'::jsonb)) RETURNING id INTO v_id;
    IF (SELECT status FROM public.property_leases WHERE id=v_id)='Active' THEN UPDATE public.property_units SET status='Occupied' WHERE id=v_unit.id; ELSE INSERT INTO public.property_approvals(company_id,entity_type,entity_id,action,requested_by) VALUES(c,'Lease',v_id,'Approve Lease',v_uid); END IF;
    INSERT INTO public.property_rent_schedules(company_id,lease_id,next_invoice_date,frequency) VALUES(c,v_id,(p_payload->>'startDate')::date,coalesce(p_payload->>'rentFrequency','Monthly'));
    INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,dedupe_key) VALUES(c,v_tenant.id,'Lease','Lease created','Your property lease has been created and is awaiting its billing cycle.','lease-created:'||v_id);
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Finance','Lease',v_id,'LEASE_CREATED',jsonb_build_object('leaseId',v_id)),(c,'CRM','Lease',v_id,'LEASE_CREATED',jsonb_build_object('tenantId',v_tenant.id));
    PERFORM public.property_audit('LEASE_CREATED','Lease',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',(SELECT status FROM public.property_leases WHERE id=v_id));
  ELSIF p_action='APPROVE_LEASE' THEN
    SELECT * INTO v_tx FROM public.property_leases WHERE id=(p_payload->>'leaseId')::uuid AND company_id=c FOR UPDATE;
    IF v_tx IS NULL OR v_tx.status<>'Pending Approval' THEN RAISE EXCEPTION 'Lease is not awaiting approval.' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.property_approvals WHERE company_id=c AND entity_type='Lease' AND entity_id=v_tx.id AND requested_by=v_uid AND status='Pending') THEN RAISE EXCEPTION 'The lease maker cannot approve their own lease.' USING ERRCODE='42501'; END IF;
    UPDATE public.property_leases SET status='Active',approved_by=v_uid,approved_at=v_now WHERE id=v_tx.id;
    UPDATE public.property_units SET status='Occupied' WHERE id=v_tx.unit_id AND company_id=c;
    UPDATE public.property_approvals SET status='Approved',decided_by=v_uid,decided_at=v_now,note=nullif(trim(p_payload->>'note'),'') WHERE company_id=c AND entity_type='Lease' AND entity_id=v_tx.id AND status='Pending';
    PERFORM public.property_audit('LEASE_APPROVED','Lease',v_tx.id,p_payload); RETURN jsonb_build_object('id',v_tx.id,'status','Active');
  ELSIF p_action='RECORD_HANDOVER' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_leases WHERE id=(p_payload->>'leaseId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Lease is unavailable for handover.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_handover_records(company_id,lease_id,handover_type,handover_date,keys_count,meter_snapshot,signed_by_tenant,signed_by_manager,notes) VALUES(c,(p_payload->>'leaseId')::uuid,coalesce(p_payload->>'handoverType','Move In'),coalesce(nullif(p_payload->>'handoverDate','')::date,current_date),coalesce(nullif(p_payload->>'keysCount','')::integer,0),coalesce(p_payload->'meterSnapshot','{}'::jsonb),coalesce((p_payload->>'signedByTenant')::boolean,false),coalesce((p_payload->>'signedByManager')::boolean,false),nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('HANDOVER_RECORDED','Handover',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Recorded');
  ELSIF p_action='RECORD_INSPECTION' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_leases WHERE id=(p_payload->>'leaseId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Lease is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_inspections(company_id,lease_id,inspection_type,inspection_date,condition_summary,status) VALUES(c,(p_payload->>'leaseId')::uuid,coalesce(p_payload->>'inspectionType','Move In'),coalesce(nullif(p_payload->>'inspectionDate','')::date,current_date),nullif(trim(p_payload->>'conditionSummary'),''),coalesce(p_payload->>'status','Completed')) RETURNING id INTO v_id;
    PERFORM public.property_audit('INSPECTION_RECORDED','Inspection',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Completed');
  ELSIF p_action='REGISTER_INSURANCE' THEN
    IF nullif(trim(p_payload->>'propertyId'),'') IS NULL AND nullif(trim(p_payload->>'unitId'),'') IS NULL THEN RAISE EXCEPTION 'Insurance must reference a property or unit.' USING ERRCODE='22023'; END IF;
    IF nullif(trim(p_payload->>'propertyId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.property_buildings WHERE id=(p_payload->>'propertyId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Insured property is unavailable.' USING ERRCODE='22023'; END IF;
    IF nullif(trim(p_payload->>'unitId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Insured unit is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_insurances(company_id,property_id,unit_id,insurer,policy_number,cover_type,premium,start_date,end_date,status,notes) VALUES(c,nullif(p_payload->>'propertyId','')::uuid,nullif(p_payload->>'unitId','')::uuid,trim(p_payload->>'insurer'),trim(p_payload->>'policyNumber'),trim(p_payload->>'coverType'),coalesce(nullif(p_payload->>'premium','')::numeric,0),(p_payload->>'startDate')::date,(p_payload->>'endDate')::date,coalesce(p_payload->>'status','Active'),nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('INSURANCE_REGISTERED','Insurance',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',coalesce(p_payload->>'status','Active'));
  ELSIF p_action='CREATE_BUDGET' THEN
    IF nullif(trim(p_payload->>'portfolioId'),'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.property_portfolios WHERE id=(p_payload->>'portfolioId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Budget portfolio is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_budgets(company_id,portfolio_id,fiscal_year,category,budget_amount,status,approved_by,approved_at) VALUES(c,nullif(p_payload->>'portfolioId','')::uuid,(p_payload->>'fiscalYear')::integer,trim(p_payload->>'category'),(p_payload->>'budgetAmount')::numeric,coalesce(p_payload->>'status','Draft'),CASE WHEN coalesce(p_payload->>'status','Draft')='Approved' THEN v_uid ELSE NULL END,CASE WHEN coalesce(p_payload->>'status','Draft')='Approved' THEN v_now ELSE NULL END) RETURNING id INTO v_id;
    PERFORM public.property_audit('BUDGET_CREATED','Budget',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',coalesce(p_payload->>'status','Draft'));
  ELSIF p_action='REGISTER_SERVICE_CHARGE' THEN
    IF NOT EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'unitId')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Service-charge unit is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_service_charges(company_id,unit_id,name,amount,frequency,status) VALUES(c,(p_payload->>'unitId')::uuid,trim(p_payload->>'name'),(p_payload->>'amount')::numeric,coalesce(p_payload->>'frequency','Monthly'),coalesce(p_payload->>'status','Active')) RETURNING id INTO v_id;
    PERFORM public.property_audit('SERVICE_CHARGE_REGISTERED','ServiceCharge',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',coalesce(p_payload->>'status','Active'));
  ELSIF p_action='GENERATE_INVOICE' THEN
    SELECT * INTO v_lease FROM public.property_leases WHERE id=(p_payload->>'leaseId')::uuid AND company_id=c AND status IN ('Active','Renewal Due') FOR UPDATE;
    IF v_lease.id IS NULL THEN RAISE EXCEPTION 'Active lease is unavailable.' USING ERRCODE='22023'; END IF;
    v_period_start:=coalesce(nullif(p_payload->>'periodStart','')::date,date_trunc('month',current_date)::date); v_period_end:=coalesce(nullif(p_payload->>'periodEnd','')::date,(v_period_start+interval '1 month-1 day')::date); v_due:=coalesce(nullif(p_payload->>'dueDate','')::date,v_period_start+7); v_amount:=CASE WHEN coalesce(p_payload->>'invoiceType','Rent')='Service Charge' THEN v_lease.service_charge_amount WHEN coalesce(p_payload->>'invoiceType','Rent')='Deposit' THEN v_lease.deposit_amount ELSE v_lease.rent_amount END;
    IF EXISTS(SELECT 1 FROM public.property_invoices WHERE company_id=c AND lease_id=v_lease.id AND invoice_type=coalesce(p_payload->>'invoiceType','Rent') AND period_start=v_period_start) THEN SELECT * INTO v_invoice FROM public.property_invoices WHERE company_id=c AND lease_id=v_lease.id AND invoice_type=coalesce(p_payload->>'invoiceType','Rent') AND period_start=v_period_start LIMIT 1; RETURN jsonb_build_object('id',v_invoice.id,'invoiceNumber',v_invoice.invoice_number,'status',v_invoice.status,'totalAmount',v_invoice.total_amount,'reused',true); END IF;
    INSERT INTO public.property_invoices(company_id,invoice_number,lease_id,tenant_id,unit_id,invoice_type,period_start,period_end,due_date,subtotal,total_amount,status,idempotency_key) VALUES(c,'PI-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_lease.id,v_lease.tenant_id,v_lease.unit_id,coalesce(p_payload->>'invoiceType','Rent'),v_period_start,v_period_end,v_due,v_amount,v_amount,'Issued','invoice:'||v_lease.id||':'||coalesce(p_payload->>'invoiceType','Rent')||':'||v_period_start) RETURNING * INTO v_invoice;
    INSERT INTO public.property_invoice_lines(company_id,invoice_id,line_type,description,quantity,unit_amount,line_total,account_code) VALUES(c,v_invoice.id,coalesce(p_payload->>'invoiceType','Rent'),coalesce(p_payload->>'description',initcap(coalesce(p_payload->>'invoiceType','Rent'))),1,v_amount,v_amount,CASE WHEN coalesce(p_payload->>'invoiceType','Rent')='Service Charge' THEN 'PROPERTY_SERVICE_CHARGE_INCOME' WHEN coalesce(p_payload->>'invoiceType','Rent')='Deposit' THEN 'PROPERTY_DEPOSIT_LIABILITY' ELSE 'PROPERTY_RENT_INCOME' END);
    v_entries:=jsonb_build_array(jsonb_build_object('accountCode','PROPERTY_RECEIVABLE','entryType','Debit','amount',v_amount),jsonb_build_object('accountCode',CASE WHEN coalesce(p_payload->>'invoiceType','Rent')='Service Charge' THEN 'PROPERTY_SERVICE_CHARGE_INCOME' WHEN coalesce(p_payload->>'invoiceType','Rent')='Deposit' THEN 'PROPERTY_DEPOSIT_LIABILITY' ELSE 'PROPERTY_RENT_INCOME' END,'entryType','Credit','amount',v_amount));
    PERFORM public.property_ledger_post('Invoice',v_invoice.id,v_entries);
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Finance','Invoice',v_invoice.id,'INVOICE_ISSUED',jsonb_build_object('invoiceId',v_invoice.id,'amount',v_amount)),(c,'Accounting','Invoice',v_invoice.id,'INVOICE_ISSUED',jsonb_build_object('invoiceId',v_invoice.id,'amount',v_amount));
    INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,dedupe_key) VALUES(c,v_lease.tenant_id,'Rent Due','Property invoice issued','Invoice '||v_invoice.invoice_number||' is due on '||v_due||'.','invoice-issued:'||v_invoice.id);
    UPDATE public.property_rent_schedules SET next_invoice_date=CASE WHEN frequency='Monthly' THEN v_period_start+interval '1 month' WHEN frequency='Quarterly' THEN v_period_start+interval '3 months' ELSE v_period_start+interval '1 year' END,last_invoice_id=v_invoice.id WHERE lease_id=v_lease.id AND company_id=c;
    PERFORM public.property_audit('INVOICE_ISSUED','Invoice',v_invoice.id,jsonb_build_object('amount',v_amount,'invoiceType',coalesce(p_payload->>'invoiceType','Rent'))); RETURN jsonb_build_object('id',v_invoice.id,'invoiceNumber',v_invoice.invoice_number,'status','Issued','totalAmount',v_amount);
  ELSIF p_action='RECORD_PAYMENT' THEN
    SELECT * INTO v_invoice FROM public.property_invoices WHERE id=(p_payload->>'invoiceId')::uuid AND company_id=c AND status NOT IN ('Paid','Voided') FOR UPDATE;
    IF v_invoice.id IS NULL THEN RAISE EXCEPTION 'Invoice is unavailable for payment.' USING ERRCODE='22023'; END IF;
    IF public.property_has_role(ARRAY['tenant','customer']) AND NOT public.property_can_finance() AND NOT EXISTS(SELECT 1 FROM public.property_tenants WHERE id=v_invoice.tenant_id AND company_id=c AND profile_id=v_uid AND status='Active') THEN RAISE EXCEPTION 'A tenant can only create a payment intent for their own invoice.' USING ERRCODE='42501'; END IF;
    v_amount:=coalesce(nullif(p_payload->>'amount','')::numeric,0); IF v_amount<=0 OR v_amount>v_invoice.total_amount-v_invoice.amount_paid THEN RAISE EXCEPTION 'Payment amount exceeds the invoice balance.' USING ERRCODE='22003'; END IF;
    v_status:=CASE WHEN coalesce(p_payload->>'paymentMethod','')='Cash' AND public.property_can_finance() THEN 'Posted' ELSE 'Provider Pending' END;
    INSERT INTO public.property_payments(company_id,payment_number,invoice_id,tenant_id,amount,payment_method,provider_code,provider_reference,status,idempotency_key,paid_at) VALUES(c,'PP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_invoice.id,v_invoice.tenant_id,v_amount,coalesce(p_payload->>'paymentMethod','Provider'),nullif(trim(p_payload->>'providerCode'),''),nullif(trim(p_payload->>'providerReference'),''),v_status,trim(p_payload->>'idempotencyKey'),CASE WHEN v_status='Posted' THEN v_now ELSE NULL END) RETURNING * INTO v_payment;
    IF v_status='Posted' THEN
      UPDATE public.property_invoices SET amount_paid=amount_paid+v_amount,status=CASE WHEN amount_paid+v_amount>=total_amount THEN 'Paid' ELSE 'Partially Paid' END WHERE id=v_invoice.id;
      INSERT INTO public.property_receipts(company_id,payment_id,receipt_number,recipient_phone) VALUES(c,v_payment.id,'PR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),(SELECT phone FROM public.property_tenants WHERE id=v_invoice.tenant_id));
      v_entries:=jsonb_build_array(jsonb_build_object('accountCode','PROPERTY_CASH','entryType','Debit','amount',v_amount),jsonb_build_object('accountCode','PROPERTY_RECEIVABLE','entryType','Credit','amount',v_amount)); PERFORM public.property_ledger_post('Payment',v_payment.id,v_entries);
      INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Finance','Payment',v_payment.id,'PAYMENT_POSTED',jsonb_build_object('paymentId',v_payment.id,'invoiceId',v_invoice.id,'amount',v_amount)),(c,'Accounting','Payment',v_payment.id,'PAYMENT_POSTED',jsonb_build_object('paymentId',v_payment.id,'invoiceId',v_invoice.id,'amount',v_amount));
      PERFORM public.property_audit('PAYMENT_POSTED','Payment',v_payment.id,jsonb_build_object('invoiceId',v_invoice.id,'amount',v_amount));
    ELSE
      INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,channel,status,dedupe_key) VALUES(c,v_invoice.tenant_id,'Payment','Payment awaiting provider confirmation','The payment intent is recorded and will remain pending until a verified provider reference is received.','In App','Pending Provider','payment-pending:'||v_payment.id);
      PERFORM public.property_audit('PAYMENT_PROVIDER_PENDING','Payment',v_payment.id,jsonb_build_object('invoiceId',v_invoice.id,'providerCode',p_payload->>'providerCode'));
    END IF;
    RETURN jsonb_build_object('id',v_payment.id,'paymentNumber',v_payment.payment_number,'status',v_status,'receiptIssued',v_status='Posted','providerReference',null);
  ELSIF p_action='CREATE_MAINTENANCE_REQUEST' THEN
    IF public.property_has_role(ARRAY['tenant']) AND NOT public.property_can_manage() THEN
      SELECT * INTO v_tenant FROM public.property_tenants WHERE company_id=c AND profile_id=v_uid AND status='Active';
      IF nullif(p_payload->>'tenantId','') IS NOT NULL AND (p_payload->>'tenantId')::uuid<>v_tenant.id THEN RAISE EXCEPTION 'A tenant can only create requests for their own linked account.' USING ERRCODE='42501'; END IF;
    ELSE
      SELECT * INTO v_tenant FROM public.property_tenants WHERE id=nullif(p_payload->>'tenantId','')::uuid AND company_id=c;
    END IF;
    IF v_tenant.id IS NULL AND NOT public.property_can_manage() THEN RAISE EXCEPTION 'A tenant profile is required for this request.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.property_maintenance_requests(company_id,request_number,unit_id,lease_id,tenant_id,category,priority,title,description,status) VALUES(c,'MR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),nullif(p_payload->>'unitId','')::uuid,nullif(p_payload->>'leaseId','')::uuid,v_tenant.id,coalesce(p_payload->>'category','General'),coalesce(p_payload->>'priority','Medium'),trim(p_payload->>'title'),trim(p_payload->>'description'),'Open') RETURNING * INTO v_request;
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Maintenance','MaintenanceRequest',v_request.id,'MAINTENANCE_REQUEST_CREATED',jsonb_build_object('requestId',v_request.id));
    PERFORM public.property_audit('MAINTENANCE_REQUEST_CREATED','MaintenanceRequest',v_request.id,p_payload); RETURN jsonb_build_object('id',v_request.id,'requestNumber',v_request.request_number,'status','Open');
  ELSIF p_action='ASSIGN_WORK_ORDER' THEN
    SELECT * INTO v_request FROM public.property_maintenance_requests WHERE id=(p_payload->>'requestId')::uuid AND company_id=c FOR UPDATE;
    IF v_request.id IS NULL THEN RAISE EXCEPTION 'Maintenance request is unavailable.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.property_work_orders(company_id,work_order_number,request_id,contractor_id,assigned_profile_id,estimated_cost,due_date,status) VALUES(c,'WO-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_request.id,nullif(p_payload->>'contractorId','')::uuid,nullif(p_payload->>'assignedProfileId','')::uuid,coalesce(nullif(p_payload->>'estimatedCost','')::numeric,0),nullif(p_payload->>'dueDate','')::date,'Assigned') RETURNING id INTO v_id;
    UPDATE public.property_maintenance_requests SET status='Assigned' WHERE id=v_request.id;
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Employee','WorkOrder',v_id,'WORK_ORDER_ASSIGNED',jsonb_build_object('assignedProfileId',p_payload->>'assignedProfileId')),(c,'Procurement','WorkOrder',v_id,'WORK_ORDER_ASSIGNED',jsonb_build_object('contractorId',p_payload->>'contractorId')),(c,'Maintenance','WorkOrder',v_id,'WORK_ORDER_ASSIGNED',jsonb_build_object('requestId',v_request.id));
    PERFORM public.property_audit('WORK_ORDER_ASSIGNED','WorkOrder',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Assigned');
  ELSIF p_action='COMPLETE_WORK_ORDER' THEN
    UPDATE public.property_work_orders SET status='Completed',actual_cost=coalesce(nullif(p_payload->>'actualCost','')::numeric,actual_cost),completion_note=nullif(trim(p_payload->>'completionNote'),''),updated_at=v_now WHERE id=(p_payload->>'workOrderId')::uuid AND company_id=c RETURNING id,request_id,actual_cost INTO v_tx;
    IF v_tx IS NULL THEN RAISE EXCEPTION 'Work order is unavailable.' USING ERRCODE='22023'; END IF;
    UPDATE public.property_maintenance_requests SET status='Completed',completed_at=v_now WHERE id=(v_tx.request_id)::uuid AND company_id=c;
    IF coalesce((v_tx.actual_cost)::numeric,0)>0 THEN INSERT INTO public.property_expenses(company_id,expense_number,work_order_id,category,description,amount,status) VALUES(c,'PE-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),(p_payload->>'workOrderId')::uuid,'Maintenance','Completed maintenance work order', (v_tx.actual_cost)::numeric,'Pending Approval'); END IF;
    PERFORM public.property_audit('WORK_ORDER_COMPLETED','WorkOrder',(p_payload->>'workOrderId')::uuid,p_payload); RETURN jsonb_build_object('id',(p_payload->>'workOrderId')::uuid,'status','Completed');
  ELSIF p_action='CREATE_EXPENSE' THEN
    INSERT INTO public.property_expenses(company_id,expense_number,property_id,unit_id,work_order_id,category,description,amount,expense_date,status,payment_method,payment_reference) VALUES(c,'PE-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),nullif(p_payload->>'propertyId','')::uuid,nullif(p_payload->>'unitId','')::uuid,nullif(p_payload->>'workOrderId','')::uuid,trim(p_payload->>'category'),trim(p_payload->>'description'),(p_payload->>'amount')::numeric,coalesce(nullif(p_payload->>'expenseDate','')::date,current_date),'Pending Approval',nullif(trim(p_payload->>'paymentMethod'),''),nullif(trim(p_payload->>'paymentReference'),'')) RETURNING id INTO v_id;
    INSERT INTO public.property_approvals(company_id,entity_type,entity_id,action,requested_by) VALUES(c,'Expense',v_id,'Approve Expense',v_uid);
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) VALUES(c,'Procurement','Expense',v_id,'EXPENSE_CREATED',jsonb_build_object('amount',p_payload->>'amount')),(c,'Finance','Expense',v_id,'EXPENSE_CREATED',jsonb_build_object('amount',p_payload->>'amount'));
    PERFORM public.property_audit('EXPENSE_CREATED','Expense',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Pending Approval');
  ELSIF p_action='APPROVE_EXPENSE' THEN
    IF EXISTS(SELECT 1 FROM public.property_approvals WHERE company_id=c AND entity_type='Expense' AND entity_id=(p_payload->>'expenseId')::uuid AND requested_by=v_uid AND status='Pending') THEN RAISE EXCEPTION 'The expense maker cannot approve their own expense.' USING ERRCODE='42501'; END IF;
    UPDATE public.property_expenses SET status='Approved',approved_by=v_uid,approved_at=v_now WHERE id=(p_payload->>'expenseId')::uuid AND company_id=c AND status='Pending Approval' RETURNING id,amount INTO v_tx;
    IF v_tx IS NULL THEN RAISE EXCEPTION 'Expense is not awaiting approval.' USING ERRCODE='22023'; END IF;
    UPDATE public.property_approvals SET status='Approved',decided_by=v_uid,decided_at=v_now WHERE company_id=c AND entity_type='Expense' AND entity_id=(p_payload->>'expenseId')::uuid AND status='Pending';
    PERFORM public.property_audit('EXPENSE_APPROVED','Expense',(p_payload->>'expenseId')::uuid,p_payload); RETURN jsonb_build_object('id',(p_payload->>'expenseId')::uuid,'status','Approved');
  ELSIF p_action='RECORD_METER_READING' THEN
    IF public.property_has_role(ARRAY['tenant','customer']) AND NOT public.property_can_manage() AND NOT EXISTS(SELECT 1 FROM public.property_utility_meters m JOIN public.property_leases l ON l.unit_id=m.unit_id JOIN public.property_tenants t ON t.id=l.tenant_id WHERE m.id=(p_payload->>'meterId')::uuid AND m.company_id=c AND t.profile_id=v_uid AND l.status IN ('Active','Renewal Due')) THEN RAISE EXCEPTION 'A tenant can only record a reading for their own active unit.' USING ERRCODE='42501'; END IF;
    SELECT rate INTO v_rate FROM public.property_utility_meters WHERE id=(p_payload->>'meterId')::uuid AND company_id=c AND status='Active';
    IF v_rate IS NULL THEN RAISE EXCEPTION 'Utility meter is unavailable.' USING ERRCODE='22023'; END IF;
    SELECT reading_value INTO v_prev FROM public.property_meter_readings WHERE company_id=c AND meter_id=(p_payload->>'meterId')::uuid ORDER BY reading_date DESC,created_at DESC LIMIT 1;
    v_amount:=coalesce(nullif(p_payload->>'readingValue','')::numeric,0); IF v_prev IS NOT NULL AND v_amount<v_prev THEN RAISE EXCEPTION 'Meter readings cannot move backwards.' USING ERRCODE='22003'; END IF;
    v_consumption:=v_amount-coalesce(v_prev,0);
    INSERT INTO public.property_meter_readings(company_id,meter_id,reading_date,reading_value,previous_value,consumption,source,notes) VALUES(c,(p_payload->>'meterId')::uuid,coalesce(nullif(p_payload->>'readingDate','')::date,current_date),v_amount,v_prev,v_consumption,coalesce(p_payload->>'source','Manual'),nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('METER_READING_RECORDED','MeterReading',v_id,jsonb_build_object('consumption',v_consumption,'rate',v_rate)); RETURN jsonb_build_object('id',v_id,'consumption',v_consumption,'estimatedCharge',round(v_consumption*v_rate));
  ELSIF p_action='ISSUE_NOTICE' THEN
    INSERT INTO public.property_notices(company_id,lease_id,tenant_id,notice_type,title,body,notice_date,effective_date,status) VALUES(c,nullif(p_payload->>'leaseId','')::uuid,nullif(p_payload->>'tenantId','')::uuid,coalesce(p_payload->>'noticeType','General'),trim(p_payload->>'title'),trim(p_payload->>'body'),coalesce(nullif(p_payload->>'noticeDate','')::date,current_date),nullif(p_payload->>'effectiveDate','')::date,'Issued') RETURNING id INTO v_id;
    INSERT INTO public.property_notifications(company_id,tenant_id,notice_id,notification_type,title,body,dedupe_key) VALUES(c,nullif(p_payload->>'tenantId','')::uuid,v_id,coalesce(p_payload->>'noticeType','General'),trim(p_payload->>'title'),trim(p_payload->>'body'),'notice:'||v_id);
    PERFORM public.property_audit('NOTICE_ISSUED','Notice',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status','Issued');
  ELSIF p_action='TERMINATE_LEASE' THEN
    UPDATE public.property_leases SET status='Terminated',terminated_at=v_now WHERE id=(p_payload->>'leaseId')::uuid AND company_id=c AND status IN ('Active','Renewal Due') RETURNING id,unit_id,tenant_id INTO v_tx;
    IF v_tx IS NULL THEN RAISE EXCEPTION 'Lease is not active.' USING ERRCODE='22023'; END IF;
    UPDATE public.property_units SET status='Available' WHERE id=(v_tx.unit_id)::uuid AND company_id=c;
    INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,dedupe_key) VALUES(c,(v_tx.tenant_id)::uuid,'Termination','Lease terminated','Your property lease has been marked terminated.','lease-terminated:'||(v_tx.id));
    PERFORM public.property_audit('LEASE_TERMINATED','Lease',(v_tx.id)::uuid,p_payload); RETURN jsonb_build_object('id',(v_tx.id)::uuid,'status','Terminated');
  ELSIF p_action='CREATE_DOCUMENT' THEN
    IF NOT ((p_payload->>'entityType'='Portfolio' AND EXISTS(SELECT 1 FROM public.property_portfolios WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Owner' AND EXISTS(SELECT 1 FROM public.property_owners WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Building' AND EXISTS(SELECT 1 FROM public.property_buildings WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Plot' AND EXISTS(SELECT 1 FROM public.property_plots WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Unit' AND EXISTS(SELECT 1 FROM public.property_units WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Agent' AND EXISTS(SELECT 1 FROM public.property_agents WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Tenant' AND EXISTS(SELECT 1 FROM public.property_tenants WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Application' AND EXISTS(SELECT 1 FROM public.property_applications WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Lease' AND EXISTS(SELECT 1 FROM public.property_leases WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Inspection' AND EXISTS(SELECT 1 FROM public.property_inspections WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Maintenance' AND EXISTS(SELECT 1 FROM public.property_maintenance_requests WHERE id=(p_payload->>'entityId')::uuid AND company_id=c)) OR (p_payload->>'entityType'='Expense' AND EXISTS(SELECT 1 FROM public.property_expenses WHERE id=(p_payload->>'entityId')::uuid AND company_id=c))) THEN RAISE EXCEPTION 'Document entity is unavailable in this workspace.' USING ERRCODE='22023'; END IF;
    IF p_payload->>'entityType'='Tenant' AND NOT EXISTS(SELECT 1 FROM public.property_tenants WHERE id=(p_payload->>'entityId')::uuid AND company_id=c AND (public.property_can_manage() OR profile_id=v_uid)) THEN RAISE EXCEPTION 'Document entity is outside the permitted tenant scope.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.property_documents(company_id,entity_type,entity_id,document_type,title,storage_key,file_url,document_date,expires_at,verification_status,metadata) VALUES(c,trim(p_payload->>'entityType'),(p_payload->>'entityId')::uuid,trim(p_payload->>'documentType'),trim(p_payload->>'title'),nullif(trim(p_payload->>'storageKey'),''),nullif(trim(p_payload->>'fileUrl'),''),nullif(p_payload->>'documentDate','')::date,nullif(p_payload->>'expiresAt','')::date,coalesce(p_payload->>'verificationStatus','Pending'),coalesce(p_payload->'metadata','{}'::jsonb)) RETURNING id INTO v_id;
    PERFORM public.property_audit('DOCUMENT_REGISTERED','Document',v_id,jsonb_build_object('entityType',p_payload->>'entityType','documentType',p_payload->>'documentType')); RETURN jsonb_build_object('id',v_id,'status','Pending');
  ELSIF p_action='RECONCILE_PAYMENT' THEN
    SELECT * INTO v_payment FROM public.property_payments WHERE id=(p_payload->>'paymentId')::uuid AND company_id=c;
    IF v_payment.id IS NULL THEN RAISE EXCEPTION 'Payment is unavailable.' USING ERRCODE='22023'; END IF;
    v_amount:=coalesce(nullif(p_payload->>'actualAmount','')::numeric,v_payment.amount); INSERT INTO public.property_reconciliations(company_id,payment_id,invoice_id,expected_amount,actual_amount,variance,status,notes) VALUES(c,v_payment.id,v_payment.invoice_id,v_payment.amount,v_amount,v_amount-v_payment.amount,CASE WHEN v_amount=v_payment.amount THEN 'Matched' ELSE 'Variance' END,nullif(trim(p_payload->>'notes'),'')) RETURNING id INTO v_id;
    PERFORM public.property_audit('PAYMENT_RECONCILED','Reconciliation',v_id,p_payload); RETURN jsonb_build_object('id',v_id,'status',CASE WHEN v_amount=v_payment.amount THEN 'Matched' ELSE 'Variance' END,'variance',v_amount-v_payment.amount);
  ELSIF p_action='RUN_PROPERTY_CONTROLS' THEN
    v_limit:=greatest(1,least(coalesce(nullif(p_payload->>'limit','')::integer,500),500));
    FOR v_lease_row IN SELECT l.*,s.id AS schedule_id,s.next_invoice_date,s.frequency FROM public.property_leases l JOIN public.property_rent_schedules s ON s.lease_id=l.id WHERE l.company_id=c AND l.status IN ('Active','Renewal Due') AND s.active AND s.next_invoice_date<=current_date ORDER BY s.next_invoice_date LIMIT v_limit LOOP
      v_period_start:=v_lease_row.next_invoice_date; v_period_end:=(v_period_start+CASE WHEN v_lease_row.frequency='Quarterly' THEN interval '3 months' WHEN v_lease_row.frequency='Annual' THEN interval '1 year' ELSE interval '1 month' END-interval '1 day')::date; v_due:=v_period_start+7;
      IF NOT EXISTS(SELECT 1 FROM public.property_invoices WHERE company_id=c AND lease_id=v_lease_row.id AND invoice_type='Rent' AND period_start=v_period_start) THEN
        INSERT INTO public.property_invoices(company_id,invoice_number,lease_id,tenant_id,unit_id,invoice_type,period_start,period_end,due_date,subtotal,total_amount,status,idempotency_key) VALUES(c,'PI-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_lease_row.id,v_lease_row.tenant_id,v_lease_row.unit_id,'Rent',v_period_start,v_period_end,v_due,v_lease_row.rent_amount,v_lease_row.rent_amount,'Issued','invoice:'||v_lease_row.id||':Rent:'||v_period_start) RETURNING id INTO v_id;
        INSERT INTO public.property_invoice_lines(company_id,invoice_id,line_type,description,unit_amount,line_total,account_code) VALUES(c,v_id,'Rent','Scheduled rent',v_lease_row.rent_amount,v_lease_row.rent_amount,'PROPERTY_RENT_INCOME');
        v_entries:=jsonb_build_array(jsonb_build_object('accountCode','PROPERTY_RECEIVABLE','entryType','Debit','amount',v_lease_row.rent_amount),jsonb_build_object('accountCode','PROPERTY_RENT_INCOME','entryType','Credit','amount',v_lease_row.rent_amount)); PERFORM public.property_ledger_post('Invoice',v_id,v_entries);
        INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,dedupe_key) VALUES(c,v_lease_row.tenant_id,'Rent Due','Rent invoice due','Rent invoice for '||v_period_start||' is due on '||v_due||'.','invoice-issued:'||v_id);
      END IF;
      UPDATE public.property_rent_schedules SET next_invoice_date=CASE WHEN frequency='Quarterly' THEN next_invoice_date+interval '3 months' WHEN frequency='Annual' THEN next_invoice_date+interval '1 year' ELSE next_invoice_date+interval '1 month' END WHERE id=v_lease_row.schedule_id;
    END LOOP;
    UPDATE public.property_invoices SET status='Overdue',late_fee_amount=CASE WHEN late_fee_amount=0 THEN round(total_amount*0.01) ELSE late_fee_amount END,total_amount=CASE WHEN late_fee_amount=0 THEN total_amount+round(total_amount*0.01) ELSE total_amount END WHERE company_id=c AND status IN ('Issued','Partially Paid') AND due_date<current_date AND amount_paid<total_amount;
    INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) SELECT c,'Finance','Property Controls',c,'PROPERTY_CONTROLS_RUN',jsonb_build_object('runAt',v_now) WHERE NOT EXISTS(SELECT 1 FROM public.property_integration_events WHERE company_id=c AND target_module='Finance' AND event_type='PROPERTY_CONTROLS_RUN' AND created_at>v_now-interval '1 hour');
    PERFORM public.property_audit('PROPERTY_CONTROLS_RUN','PropertyControls',c,jsonb_build_object('runAt',v_now)); RETURN jsonb_build_object('status','Completed','runAt',v_now);
  ELSE RAISE EXCEPTION 'Unsupported Property Management action.' USING ERRCODE='22023';
  END IF;
END; $$;

CREATE OR REPLACE FUNCTION public.property_run_controls_for_company(p_company_id uuid,p_limit integer DEFAULT 500) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE r record; v_limit integer:=greatest(1,least(coalesce(p_limit,500),500)); v_invoice_id uuid; v_period_start date; v_period_end date; v_due date; v_run_at timestamptz:=now(); v_count integer:=0;
BEGIN
  IF current_setting('request.jwt.claim.role',true)<>'service_role' THEN RAISE EXCEPTION 'Property controls require service-role scheduling.' USING ERRCODE='42501'; END IF;
  FOR r IN SELECT l.*,s.id AS schedule_id,s.next_invoice_date,s.frequency FROM public.property_leases l JOIN public.property_rent_schedules s ON s.lease_id=l.id WHERE l.company_id=p_company_id AND l.status IN ('Active','Renewal Due') AND s.active AND s.next_invoice_date<=current_date ORDER BY s.next_invoice_date LIMIT v_limit LOOP
    v_period_start:=r.next_invoice_date; v_period_end:=(v_period_start+CASE WHEN r.frequency='Quarterly' THEN interval '3 months' WHEN r.frequency='Annual' THEN interval '1 year' ELSE interval '1 month' END-interval '1 day')::date; v_due:=v_period_start+7;
    IF NOT EXISTS(SELECT 1 FROM public.property_invoices WHERE company_id=p_company_id AND lease_id=r.id AND invoice_type='Rent' AND period_start=v_period_start) THEN
      INSERT INTO public.property_invoices(company_id,invoice_number,lease_id,tenant_id,unit_id,invoice_type,period_start,period_end,due_date,subtotal,total_amount,status,idempotency_key,created_by) VALUES(p_company_id,'PI-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),r.id,r.tenant_id,r.unit_id,'Rent',v_period_start,v_period_end,v_due,r.rent_amount,r.rent_amount,'Issued','invoice:'||r.id||':Rent:'||v_period_start,NULL) RETURNING id INTO v_invoice_id;
      INSERT INTO public.property_invoice_lines(company_id,invoice_id,line_type,description,unit_amount,line_total,account_code) VALUES(p_company_id,v_invoice_id,'Rent','Scheduled rent',r.rent_amount,r.rent_amount,'PROPERTY_RENT_INCOME');
      INSERT INTO public.property_ledger_entries(company_id,source_type,source_id,account_code,entry_type,amount) VALUES(p_company_id,'Invoice',v_invoice_id,'PROPERTY_RECEIVABLE','Debit',r.rent_amount),(p_company_id,'Invoice',v_invoice_id,'PROPERTY_RENT_INCOME','Credit',r.rent_amount);
      INSERT INTO public.property_notifications(company_id,tenant_id,notification_type,title,body,dedupe_key) VALUES(p_company_id,r.tenant_id,'Rent Due','Rent invoice due','Rent invoice for '||v_period_start||' is due on '||v_due||'.','invoice-issued:'||v_invoice_id);
      v_count:=v_count+1;
    END IF;
    UPDATE public.property_rent_schedules SET next_invoice_date=CASE WHEN frequency='Quarterly' THEN next_invoice_date+interval '3 months' WHEN frequency='Annual' THEN next_invoice_date+interval '1 year' ELSE next_invoice_date+interval '1 month' END WHERE id=r.schedule_id;
  END LOOP;
  UPDATE public.property_invoices SET status='Overdue',late_fee_amount=CASE WHEN late_fee_amount=0 THEN round(total_amount*0.01) ELSE late_fee_amount END,total_amount=CASE WHEN late_fee_amount=0 THEN total_amount+round(total_amount*0.01) ELSE total_amount END WHERE company_id=p_company_id AND status IN ('Issued','Partially Paid') AND due_date<current_date AND amount_paid<total_amount;
  INSERT INTO public.property_integration_events(company_id,target_module,entity_type,entity_id,event_type,payload) SELECT p_company_id,'Finance','Property Controls',p_company_id,'PROPERTY_CONTROLS_RUN',jsonb_build_object('runAt',v_run_at,'source','scheduled') WHERE NOT EXISTS(SELECT 1 FROM public.property_integration_events WHERE company_id=p_company_id AND target_module='Finance' AND event_type='PROPERTY_CONTROLS_RUN' AND created_at>v_run_at-interval '1 hour');
  INSERT INTO public.property_audit_log(company_id,actor_id,action,entity_type,entity_id,details) VALUES(p_company_id,NULL,'PROPERTY_CONTROLS_RUN','PropertyControls',p_company_id,jsonb_build_object('runAt',v_run_at,'source','scheduled','invoicesCreated',v_count));
  RETURN jsonb_build_object('status','Completed','companyId',p_company_id,'invoicesCreated',v_count,'runAt',v_run_at);
END; $$;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['property_portfolios','property_owners','property_buildings','property_plots','property_units','property_listings','property_agents','property_tenants','property_tenant_documents','property_applications','property_leases','property_inspections','property_inspection_items','property_handover_records','property_rent_schedules','property_tax_fee_rules','property_service_charges','property_utility_meters','property_meter_readings','property_invoices','property_invoice_lines','property_payments','property_receipts','property_contractors','property_maintenance_requests','property_work_orders','property_expenses','property_budgets','property_insurances','property_documents','property_notices','property_approvals','property_ledger_entries','property_reconciliations','property_notifications','property_integration_events','property_audit_log'] LOOP
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon,authenticated',t);
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.property_has_role(text[]) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_can_view() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_can_manage() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_can_finance() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_can_approve() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_can_audit() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_require(text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_audit(text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_ledger_post(text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_snapshot(integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_tenant_snapshot(integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_action(text,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.property_run_controls_for_company(uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.property_run_controls_for_company(uuid,integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.property_snapshot(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.property_tenant_snapshot(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.property_action(text,jsonb) TO authenticated;

COMMIT;
